def vowel_back(s):
    result = []
    vowels = "aeiou"
    exceptions = {'c': -1, 'o': -1, 'd': -3, 'e': -4}

    for char in s:
        original_char = char
        new_char = char

        if char in exceptions:
            shift = exceptions[char]
        elif char in vowels:
            shift = -5
        else:
            shift = 9

        current_pos = ord(char) - ord('a')
        new_pos = (current_pos + shift) % 26
        new_char = chr(new_pos + ord('a'))

        if new_char in 'code':
            new_char = original_char

        result.append(new_char)

    return ''.join(result)
